  { bulto: 4, cliente: 3, tel: "11-4411-7482", deposito: "Dock Sur" },
  { bulto: 5, cliente: 3, tel: "11-4411-7482", deposito: "Dock Sur" },
];

// ¿X determina Y? Devuelve los valores de X que tienen más de un valor de Y.
function refutaciones(filas, X, Y) {
  const vistos = new Map();
  for (const f of filas) {
    const k = X.map((c) => f[c]).join("|");
    if (!vistos.has(k)) vistos.set(k, new Set());
    vistos.get(k).add(Y.map((c) => f[c]).join("|"));
  }
  return [...vistos].filter(([, ys]) => ys.size > 1).map(([k, ys]) => `${k} -> ${[...ys].join(" / ")}`);
}

for (const [X, Y] of [[["cliente"], ["tel"]], [["cliente"], ["deposito"]], [["bulto"], ["cliente", "tel"]]]) {
  const r = refutaciones(filas, X, Y);
  console.log(`${X.join("+")} -> ${Y.join("+")}:`, r.length ? "REFUTADA por " + r.join("; ") : "ninguna fila la refuta");
}

